package com.bank.equality;

import java.math.BigDecimal;
import java.util.logging.*;

public class EqualityDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountMatcher matcher = new AccountMatcher();

        // Case 1: string literals are interned -> == accidentally works
        String literalA = "SAV2001";
        String literalB = "SAV2001";
        log.info(() -> "literal == literal : " + (literalA == literalB));          // true
        log.info(() -> "literal .equals()  : " + literalA.equals(literalB));        // true

        // Case 2: new String makes a distinct object -> == breaks
        String fromDb = new String("SAV2001");
        log.info(() -> "literal == new     : " + (literalA == fromDb));             // false (BUG)
        log.info(() -> "literal .equals new: " + literalA.equals(fromDb));          // true (CORRECT)
        log.info(() -> "after intern() ==  : " + (literalA == fromDb.intern()));    // true

        // Case 3: Integer cache -128..127
        Integer small1 = 100, small2 = 100;
        Integer big1 = 1000, big2 = 1000;
        log.info(() -> "Integer 100 ==     : " + (small1 == small2));               // true (cached)
        log.info(() -> "Integer 1000 ==    : " + (big1 == big2));                   // false (uncached)

        // Case 4: money must use compareTo, never ==
        matcher.matchAccountId("SAV2001", fromDb);
        matcher.matchAmount(new BigDecimal("50000"), new BigDecimal("50000.00"));
    }
}

// ─── Would be Account.java in a real project ───
class Account {
    private final String accountId;
    private BigDecimal balance;
    Account(String id, BigDecimal bal) { accountId=id; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be AccountMatcher.java in a real project ───
class AccountMatcher {
    private static final Logger log = Logger.getLogger("BankLog");

    void matchAccountId(String a, String b) {
        boolean wrong = (a == b);            // compares references
        boolean right = a.equals(b);         // compares content
        log.warning(() -> "ID  == gives " + wrong + " (unreliable)");
        log.info(() -> "ID  .equals gives " + right + " (correct)");
    }

    // For money, equals() is also strict about scale: 50000 vs 50000.00 are NOT equals()
    // but ARE equal by compareTo. compareTo is the correct value check for money.
    void matchAmount(BigDecimal a, BigDecimal b) {
        boolean byEquals = a.equals(b);          // false: different scale
        boolean byCompare = a.compareTo(b) == 0; // true: same numeric value
        log.warning(() -> "Money .equals gives " + byEquals + " (scale-sensitive)");
        log.info(() -> "Money compareTo==0 gives " + byCompare + " (correct for value)");
    }
}
