package com.bank.rates;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinalAssignDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        final int a = 20;          // final primitive, compile-time constant
        int b = a;                 // ALLOWED: read a, copy value into b
        final int c = a;           // ALLOWED: c assigned once, from a's value
        b = b + 5;                 // ALLOWED: b is NOT final, change it freely
        // a = 30;                 // COMPILE ERROR: cannot reassign final a

        log.info(() -> "a (final) = " + a);
        log.info(() -> "b (copied then +5) = " + b);
        log.info(() -> "c (final copy of a) = " + c);

        InterestEngine engine = new InterestEngine();
        engine.classifyTier(a);
        BigDecimal interest = engine.monthlyInterest(new BigDecimal("1000000.00"), a);
        log.info(() -> "Interest for SAV2001 (Rajesh) = Rs." + interest);
    }
}

// ─── Would be RateCard.java in a real project ───
class RateCard {
    static final int PROMO_RATE_PERCENT = 20; // fixed, cannot be reassigned
}

// ─── Would be InterestEngine.java in a real project ───
class InterestEngine {
    private static final Logger log = Logger.getLogger("BankLog");

    // A final primitive constant can be used as a switch label (constant folding).
    void classifyTier(final int ratePercent) {
        int working = ratePercent; // copy final value into a mutable local
        switch (working) {
            case 20 -> log.info("Rate 20% classified as PROMO tier");
            default -> log.info("Standard tier");
        }
    }

    java.math.BigDecimal monthlyInterest(BigDecimal principal, int ratePercent) {
        return principal.multiply(BigDecimal.valueOf(ratePercent))
                        .divide(new BigDecimal("100"), 2, java.math.RoundingMode.HALF_EVEN)
                        .divide(new BigDecimal("12"), 2, java.math.RoundingMode.HALF_EVEN);
    }
}
