package com.bank.cleanup;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinalFinallyFinalizeDemo {
    // 'final' keyword: a fixed constant, assigned once, cannot change.
    static final BigDecimal TRANSFER_FEE = new BigDecimal("10.00");

    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        TransferService service = new TransferService(repo);

        log.info("--- Successful transfer ---");
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        log.info("--- Failing transfer (insufficient funds) ---");
        try {
            service.transfer("CUR3001", "SAV2001", new BigDecimal("999999999"));
        } catch (RuntimeException e) {
            log.log(Level.SEVERE, "Transfer failed but ledger still closed", e);
        }
    }
}

